import{_ as n,H as t,f as a,i as l}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"19-Sentinel实战：如何为项目添加异常降级方案？","description":"","frontmatter":{},"headers":[{"level":2,"title":"编写降级逻辑","slug":"编写降级逻辑","link":"#编写降级逻辑","children":[]},{"level":2,"title":"在控制台添加熔断策略","slug":"在控制台添加熔断策略","link":"#在控制台添加熔断策略","children":[]},{"level":2,"title":"Sentinel 熔断开关的状态转换","slug":"sentinel-熔断开关的状态转换","link":"#sentinel-熔断开关的状态转换","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"SpringCloud微服务项目实战/19-Sentinel实战：如何为项目添加异常降级方案？.md","filePath":"SpringCloud微服务项目实战/19-Sentinel实战：如何为项目添加异常降级方案？.md","lastUpdated":1795535212000}'),i={name:"SpringCloud微服务项目实战/19-Sentinel实战：如何为项目添加异常降级方案？.md"};function p(s,e,o,E,c,r){return t(),a("div",null,[...e[0]||(e[0]=[l(`<h1 id="_19-sentinel实战-如何为项目添加异常降级方案" tabindex="-1">19-Sentinel实战：如何为项目添加异常降级方案？ <a class="header-anchor" href="#_19-sentinel实战-如何为项目添加异常降级方案" aria-label="Permalink to &quot;19-Sentinel实战：如何为项目添加异常降级方案？&quot;">​</a></h1><p>你好，我是姚秋辰。</p><p>上节课我们学习了如何将应用接入 Sentinel 实现不同的流控效果，今天我们来学习 Sentinel组件另一个重要功能：降级熔断。通过这节课，你可以知道如何通过 Sentinel 的熔断策略处理各种调用异常。除此之外，我还会讲解 Sentinel 熔断器开关的状态变化过程。</p><p>在第 17 课中我们学习过降级和熔断的作用，今天我们就先从降级开始，了解一下如何利用Sentinel 的注解指定降级方法。</p><p>这里我将以 Template 服务的模板批量查询接口为例，向你演示如何设置降级方法。为什么我会选择这个接口？因为券模板查询是一个基础服务，很多上游的业务场景都依赖这个接口获取模板信息，所以它的访问压力相比于其它接口就大得多了，也更容易发生各种服务超时之类的异常情况。</p><p>如果你已经准备好了，我们就从编写降级逻辑开始吧。</p><h2 id="编写降级逻辑" tabindex="-1">编写降级逻辑 <a class="header-anchor" href="#编写降级逻辑" aria-label="Permalink to &quot;编写降级逻辑&quot;">​</a></h2><p>上一节课中，我们在 Template 服务的批量领劵接口之上添加了一个 SentinelResource 注解，并在其中使用 blockHandler 属性指定了降级方法的名称。不过呢，这个注解可不是一个万金油注解，它只能在服务抛出 BlockException 的情况下执行降级逻辑。</p><p>什么是 BlockException 呢？这个异常类是 Sentinel 组件自带的类，当一个请求被 Sentinel 规则拦截，这个异常便会被抛出。比如请求被 Sentinel 流控策略阻拦住，或者请求被熔断策略阻断了，这些情况下你可以使用 SentinelResource 的 blockHandler 注解来指定降级逻辑。但是对于其它 RuntimeException 的异常类型它就无能为力了。</p><p>我们如何指定一段通用的降级逻辑，来应对 BlockException 以外的 RuntimeException 呢？你可以使用 SentinelResource 中的另一个属性：fallback。</p><p>以 Template 服务的批量查询接口为例，我通过 fallback 属性指定了一段降级逻辑，用来处理各种运行期异常的情况。你可以参考下面这段代码。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@GetMapping(&quot;/getBatch&quot;)</span></span>
<span class="line"><span>@SentinelResource(value = &quot;getTemplateInBatch&quot;,</span></span>
<span class="line"><span>       fallback = &quot;getTemplateInBatch_fallback&quot;,</span></span>
<span class="line"><span>       blockHandler = &quot;getTemplateInBatch_block&quot;)</span></span>
<span class="line"><span>public Map&lt;​Long, CouponTemplateInfo&gt; getTemplateInBatch(</span></span>
<span class="line"><span>       @RequestParam(&quot;ids&quot;) Collection&lt;​Long&gt; ids) {</span></span>
<span class="line"><span>   // 如果接口被熔断，那么下面这行log不会被打印出来</span></span>
<span class="line"><span>   log.info(&quot;getTemplateInBatch: {}&quot;, JSON.toJSONString(ids));</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// 接口被降级时的方法</span></span>
<span class="line"><span>public Map&lt;​Long, CouponTemplateInfo&gt; getTemplateInBatch_fallback(</span></span>
<span class="line"><span>       Collection&lt;​Long&gt; ids) {</span></span>
<span class="line"><span>   log.info(&quot;接口被降级&quot;);</span></span>
<span class="line"><span>   return Maps.newHashMap();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在这段代码中，我通过 fallback 属性指定了当前资源的降级方法是getTemplatInBatch_fallback。</p><p>这里你需要注意，如果降级方法的方法签名是 BlockException，那么 fallback 是无法正常工作的。这点和 blockHandler 属性的用法是不一样的。我在注解中同时使用了 fallback 和blockHandler 属性，如果服务抛出 BlockException，则执行 blockHandler 属性指定的方法，其他异常就由 fallback 属性所对应的降级方法接管。</p><p>如果你不想把降级方法定义在当前 Class 中，而是想新建一个 Class 来统一管理这些降级逻辑，那么你可以通过 SentinelResource 注解的 fallbackClass 属性指定一个保存降级逻辑的Class。</p><p>在大多数的实际场景下，我们在降级方法中执行的是静默逻辑，即尽可能返回一个可被服务处理的默认值。举个例子，对于商品详情页的营销优惠计算服务来说，如果发生了服务异常导致的降级，我们可以在服务中返回商品原价，并通过一个特殊标记或属性告诉前端优惠计算发生错误，让前端页面可以根据这个异常标记显示特定提示信息。</p><p>定义好降级逻辑，接下来我们就可以去 Sentinel 控制台设置熔断策略了。</p><h2 id="在控制台添加熔断策略" tabindex="-1">在控制台添加熔断策略 <a class="header-anchor" href="#在控制台添加熔断策略" aria-label="Permalink to &quot;在控制台添加熔断策略&quot;">​</a></h2><p>你可以将 Sentinel 控制台和本地微服务模块一同启动。然后，登录 Sentinel 控制台并展开coupon-template-serv 模块的导航栏，并在“熔断规则”面板中新建一个规则。</p><p>你会看到，Sentinel 的熔断规则有 3 种，分别是异常比例、异常数和慢调用比例。我们可以分别看看它们是如何使用的。</p><p>首先，你可以指定以“异常比例”为熔断开关的判断逻辑。在 10 秒的统计窗口内，如果异常调用的比例超过了 60%，并且满足请求数量 &gt;=5，就开启一段为期 5 秒的熔断时间。</p><p>我录了一段 video，你可以参考一下具体的设置规则。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/19-Sentinel%25E5%25AE%259E%25E6%2588%2598/1.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/19-Sentinel%25E5%25AE%259E%25E6%2588%2598/1.jpeg" alt=""></a></p><p>在设置过程中，你一定要注意界面上显示的时间单位。“熔断时长”的时间单位是秒，而“统计窗口”的时间单位是毫秒，这两者很容易弄混。</p><p>接下来，你可以故意在代码中选择性地抛出一个 RuntimeException，比如当 Template 服务批量查询服务的 ID 数量为 3 时抛出异常，这样你就可以验证熔断器的效果了。</p><p>我画了一张流程图，可以帮助你理解 Sentinel 的熔断规则的统计方式，我们一起来看一下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/19-Sentinel%25E5%25AE%259E%25E6%2588%2598/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/19-Sentinel%25E5%25AE%259E%25E6%2588%2598/2.png" alt=""></a></p><p>从图中你可以看出，Sentinel 底层通过一段跨度为 10 秒的滑动窗口来统计服务调用情况。在这段窗口时间内，前三个服务请求全部失败，这时失败率已经达到 100%，大大超过了我们定义的 60% 的阈值，但是熔断开关却没有打开，这是因为统计窗口的最小请求数还没有达到设定值 5。</p><p>之后又有两个请求被处理，一个成功一个失败，这时请求个数已经达到了 5，失败率是 80%，那么 Sentinel 就开启了一段 5 秒的熔断时间。在这段时间内，所有来访请求都不会得到真实的执行，而是转而执行降级逻辑。</p><p>为了验证在熔断期间只有降级逻辑会被执行，你可以在 getTemplateInBatch 方法的第一行打印一条日志信息，我们预期的结果是，在熔断期间这行日志不会被打印到控制台。</p><p>你已经了解了如何基于异常比例添加熔断规则，接下来我们就趁热打铁，去看看如何根据“异常数”和“慢调用比例”来设置熔断规则。</p><p>“异常数”熔断规则和前面我们设置的异常比例熔断规则几乎一样，唯一的区别就是“异常数”的判定条件是统计窗口内发生异常的个数，而不是去统计异常请求的比例。在下面这张图里，我设置了一个基于异常数判定的规则，即 getTemplateInBatch 请求在 10 秒内异常数 &gt;2，则触发 5 秒的熔断窗口。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/19-Sentinel%25E5%25AE%259E%25E6%2588%2598/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/19-Sentinel%25E5%25AE%259E%25E6%2588%2598/3.png" alt=""></a></p><p>在这里我想提醒你注意，熔断器开启的判定条件是异常数 &gt;2，注意这里是大于2 而不是大于等于 2。也就是说，即便在窗口期内你调用了 5 次接口，其中有 2 个接口发生了异常，那么你也要等下一次失败调用发生之后，才能满足异常数大于 2 的判定条件，触发熔断。</p><p>现在，你也了解了“异常数”熔断规则。那么接下来，我们就举一反三去了解如何设置基于慢调用比例的熔断规则。通常来说，慢调用请求所占比例逐渐增多，这是服务雪崩的前兆。为了将影响范围缩小，我们要做的就是尽早捕捉到慢调用请求的比例变化趋势，及时通过熔断规则对服务进行减压。</p><p>在下面的图中，我设定了一条慢调用判定条件。在 10 秒的统计窗口内，如果响应时间大于1000ms 的请求所占总请求数量的比例超过了 0.4，并且请求总数量 &gt;=5，此时将触发Sentinel 的熔断开关，开启 5 秒的熔断窗口。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/19-Sentinel%25E5%25AE%259E%25E6%2588%2598/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/19-Sentinel%25E5%25AE%259E%25E6%2588%2598/4.png" alt=""></a></p><p>需要注意的是，当服务请求超过设置的最大响应时间，Sentinel 只是会将该次请求作为一次慢响应加入到统计数据里，并不会将这个请求直接阻塞掉。因此，这里的最大 RT 只是一个用来做统计的条件参数，而不是超时判定的参数。</p><p>在真实业务中，“慢调用”是一个关键侦测指标，拿阿里系的应用监控为例，业务层有 RT 监控，DB 层也有慢 SQL 监控，目的就是将可能的服务雪崩扼杀于摇篮之中。因为当服务响应逐渐变慢的时候，说明集群所承接的业务流量也在同步增加，当 RT 越来越大直到达到一个阈值的时候，集群的吞吐量必然会迎来一个拐点。这个拐点也是全链路压测时要获取的一个关键指标，它是集群吞吐量的极限。</p><p>到这里，相信你已经对 Sentinel 的熔断策略有了全面的了解。但是，你知道 Sentinel 是如何判定熔断开关的开启和关闭吗？也许你会以为只要熔断时间结束，Sentinel 就会立即回到正常状态。你只答对了一半，在熔断开关的开启和关闭之间，其实还有一个半开状态。接下来我就带你去了解 Sentinel 的熔断状态转换规则。</p><h2 id="sentinel-熔断开关的状态转换" tabindex="-1">Sentinel 熔断开关的状态转换 <a class="header-anchor" href="#sentinel-熔断开关的状态转换" aria-label="Permalink to &quot;Sentinel 熔断开关的状态转换&quot;">​</a></h2><p>Sentinel 的熔断器会在开启、关闭和半开这三种逻辑状态之间来回切换，为了方便你理解整个过程，我画了一张图来解释熔断器的状态变化，你可以参考一下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/19-Sentinel%25E5%25AE%259E%25E6%2588%2598/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/19-Sentinel%25E5%25AE%259E%25E6%2588%2598/5.png" alt=""></a></p><p>从图中你可以看出，在第一个统计窗口内熔断器是处于关闭状态的，达到熔断判定条件之后，Sentinel 开启了一段熔断窗口。在这段窗口时间内，熔断器是处于开启状态的，这时新的服务请求会执行降级逻辑。待熔断窗口结束，Sentinel 会将熔断器状态置为“半开”状态，这是一个介于完全开启和完全关闭之间的中间态。</p><p>在半开状态下，如果有一个新请求过来，那么 Sentinel 会试探性地让这个请求去执行正常的业务逻辑，如果执行成功，那么 Sentinel 将关闭熔断器并退出熔断状态，如果执行失败，那么Sentinel 将再次开启一个新的熔断窗口。</p><p>从这里我们可以得出一个信息，当熔断器处于“半开”状态时，只要下一个请求失败，就立即打回熔断状态，并不需要再次满足熔断规则中设置的各种条件。</p><p>到这里，相信你已经对 Sentinel 的熔断机制都有了比较全面的认识。现在，我们就来回顾一下这节课的重点内容吧。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>今天我带你了解了 Sentinel 的三种熔断策略，分别是慢调用比例、异常比例、异常数，你还知道了这三种策略背后的熔断状态流转过程。借助 Sentinel 的三种熔断策略，我们可以对各种潜在的异常调用进行防范，并及时对异常链路做熔断处理，降低服务的访问压力。</p><p>在实际的业务场景中，慢调用比例和异常比例是两个比较常用的熔断策略。因为无论当前服务处于低水位还是高水位，百分比数据都能够从统一口径反映出服务稳定性情况。</p><p>但是对于异常数来说，在低水位和高水位下就会产生一些统计偏差，比如我设置异常数 &gt;5 触发熔断，在 QPS=20 的情况下，这个判定条件看起来没什么问题，但当 QPS=200 的情况下，只要有 2.5% 的请求失败就会进入熔断状态，这显然并不合理。</p><p>因此，我个人比较推荐你在项目中使用慢调用和异常比例策略作为容错规则，这样不管集群当前水位高还是低，都能获得一个相对准确的判定标准。</p><p>不知你是否注意到了，我们之前添加的限流规则和熔断规则都是临时数据，并没有持久化到某个存储介质中，所以每次重启控制台和应用的时候，这些规则都会消失不见，你还得去重新设置一遍，这显然是很不方便的。所以下一节课，我要带你解决这个问题，看看我们如何借助Nacos 实现限流规则的持久化。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>通过这节课的内容，你能结合 Sentinel 的源代码，去深入了解熔断策略的底层实现吗？我还是先把藤交到你手上，你可以先尝试找到哪个 Slot 类处理了熔断降级判定，再进一步了解每个不同的熔断策略对应了源码中的哪个类。如果你顺藤摸瓜往下探索，就能了解整个流程的全貌了。</p><p>好啦，这节课就结束啦。欢迎你把这节课分享给更多对 Spring Cloud 感兴趣的朋友。我是姚秋辰，我们下节课再见！</p>`,56)])])}const h=n(i,[["render",p]]);export{u as __pageData,h as default};
